'use strict';

// MODULES //

var sincos = require( '@stdlib/math/base/special/sincos' ).assign;
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var floor = require( '@stdlib/math/base/special/floor' );
var decompose = require( './decompose.js' );


// VARIABLES //

// Define a list of initial trial factors for FFT factorization:
var TRIAL_FACTORS = [ 4, 2, 3, 5 ];


// MAIN //

/**
* Initializes the working arrays for applying a Fourier transform to a real-valued sequence.
*
* @private
* @param {NonNegativeInteger} N - length of the sequence
* @param {Collection} twiddles - array of twiddle factors
* @param {NonNegativeInteger} offsetT - starting index for twiddles
* @param {Collection} factors - array containing factorization information
* @param {NonNegativeInteger} offsetF - starting index for factors
* @returns {void}
*/
function rffti1( N, twiddles, offsetT, factors, offsetF ) { // FIXME: accommodate strides for twiddles and factors
	var argld;
	var argh;
	var ido;
	var arg;
	var nf;
	var ip;
	var is;
	var ii;
	var ld;
	var fi;
	var l2;
	var l1;
	var k;
	var j;
	var i;

	// Decompose the sequence length into its prime factors:
	nf = decompose( N, TRIAL_FACTORS, factors, 1, offsetF ); // FIXME: allow non-unit stride
	if ( nf-1 === 0 ) {
		return;
	}

	// FIXME: document this loop sequence
	argh = TWO_PI / N;
	is = 0;
	l1 = 1;
	for ( k = 1; k < nf; k++ ) {
		ip = factors[ offsetF+k+1 ]; // FIXME: adjust for a stride in factors
		ld = 0;
		l2 = ip * l1;
		ido = floor( N / l2 );
		for ( j = 1; j < ip; j++ ) {
			ld += l1;
			i = is;
			argld = ld * argh;
			fi = 0.0;
			for ( ii = 3; ii <= ido; ii += 2 ) {
				i += 2;
				fi += 1.0;
				arg = fi * argld;

				// FIXME: adjust for a stride in twiddles
				sincos( arg, twiddles, -1, offsetT+i+1 ); // note: cosine before sine
			}
			is += ido;
		}
		l1 = l2;
	}
}


// EXPORTS //

module.exports = rffti1;
